const QUEST_TRACES=[{"id": "t1-1", "week": 1, "title": "Rebinding a name", "code": "hp = 30\nhp = hp - 12\nhp += 5\nprint(hp)", "output": "23", "why": "Each assignment replaces the value bound to hp: 30, then 18, then 23."}, {"id": "t1-2", "week": 1, "title": "First matching branch", "code": "def label(score):\n    if score >= 90:\n        return \"S\"\n    if score >= 70:\n        return \"A\"\n    return \"B\"\n\nprint(label(70), label(95), label(12))", "output": "A S B", "why": "return exits immediately, so only the first true condition matters. 70 is not >= 90 but is >= 70."}, {"id": "t2-1", "week": 2, "title": "A running total", "code": "total = 0\nfor n in [3, 4, 5]:\n    total += n\n    print(total)", "output": "3\n7\n12", "why": "print is inside the loop, so it runs once per item with the total so far."}, {"id": "t2-2", "week": 2, "title": "Chained string methods", "code": "name = \"  Dark Souls \"\nprint(name.strip().lower().replace(\" \", \"_\"))", "output": "dark_souls", "why": "Methods apply left to right: strip outer spaces, lowercase, then replace the inner space."}, {"id": "t3-1", "week": 3, "title": "Counting with get", "code": "inv = {\"potion\": 2}\ninv[\"potion\"] += 1\ninv[\"key\"] = inv.get(\"key\", 0) + 1\nprint(inv)", "output": "{'potion': 3, 'key': 1}", "why": "get returns the default 0 for a missing key, so key becomes 1. Dicts keep insertion order."}, {"id": "t3-2", "week": 3, "title": "Sorting by a field", "code": "scores = [(\"ana\", 5), (\"bo\", 9), (\"cy\", 7)]\nranked = sorted(scores, key=lambda p: p[1], reverse=True)\nprint(ranked[0][0], len(ranked))", "output": "bo 3", "why": "The key picks the score; reverse=True puts the highest first. sorted keeps every item."}, {"id": "t4-1", "week": 4, "title": "Clamped damage", "code": "hp = 10\nfor dmg in [4, 7, 3]:\n    hp = max(0, hp - dmg)\nprint(hp)", "output": "0", "why": "10-4=6, then 6-7 would be -1 but max clamps it to 0, then 0-3 clamps to 0 again."}, {"id": "t4-2", "week": 4, "title": "Walking a grid", "code": "x, y = 0, 0\nfor c in \"NNEWS\":\n    if c == \"N\":\n        y += 1\n    elif c == \"S\":\n        y -= 1\n    elif c == \"E\":\n        x += 1\n    elif c == \"W\":\n        x -= 1\nprint(x, y)", "output": "0 1", "why": "N,N puts y at 2; E then W cancel out on x; S brings y back to 1."}, {"id": "t5-1", "week": 5, "title": "Where range stops", "code": "total = 0\nfor i in range(1, 5):\n    total += i\nprint(total)", "output": "10", "why": "range(1, 5) stops before 5: 1+2+3+4 = 10. This is the classic off-by-one."}, {"id": "t5-2", "week": 5, "title": "What int accepts", "code": "def parse(text):\n    try:\n        return int(text)\n    except ValueError:\n        return None\n\nprint(parse(\"42\"), parse(\"4.2\"), parse(\" 7 \"))", "output": "42 None 7", "why": "int rejects a decimal string with ValueError, but it ignores surrounding whitespace."}, {"id": "t6-1", "week": 6, "title": "Parsing JSON", "code": "import json\ndata = json.loads('{\"hp\": 5, \"tags\": [\"a\", \"b\"]}')\nprint(data[\"hp\"] * 2, len(data[\"tags\"]))", "output": "10 2", "why": "JSON numbers become ints and arrays become lists, so normal Python operations work."}, {"id": "t6-2", "week": 6, "title": "Suffix vs stem", "code": "from pathlib import Path\np = Path(\"saves/slot1.backup.json\")\nprint(p.suffix, p.stem)", "output": ".json slot1.backup", "why": "suffix is only the last extension; stem is the file name minus that last suffix."}, {"id": "t7-1", "week": 7, "title": "Spot the collision", "code": "names = [\"My Save\", \"my_save\", \"Boss\"]\nplan = [n.lower().replace(\" \", \"_\") for n in names]\nprint(plan)\nprint(len(set(plan)))", "output": "['my_save', 'my_save', 'boss']\n2", "why": "Two different sources normalize to the same target, so the set has only 2 unique names."}, {"id": "t7-2", "week": 7, "title": "Clean, dedupe, sort", "code": "tags = [\" RPG\", \"rpg\", \"\", \"Indie \"]\nclean = sorted({t.strip().lower() for t in tags if t.strip()})\nprint(clean)", "output": "['indie', 'rpg']", "why": "The empty tag is filtered out; the set merges the two rpg spellings; sorted returns a list."}, {"id": "t8-1", "week": 8, "title": "Stop at the first repeat", "code": "seen = set()\nfor n in [4, 1, 4, 2]:\n    if n in seen:\n        print(\"dup\", n)\n        break\n    seen.add(n)\nprint(len(seen))", "output": "dup 4\n2", "why": "break exits before 2 is ever added, so seen holds only 4 and 1."}, {"id": "t8-2", "week": 8, "title": "Sorted characters", "code": "print(sorted(\"listen\") == sorted(\"silent\"), sorted(\"cab\"))", "output": "True ['a', 'b', 'c']", "why": "sorted on a string returns a list of characters. Anagrams produce identical sorted lists."}, {"id": "t9-1", "week": 9, "title": "A stack of brackets", "code": "stack = []\nfor ch in \"(()\":\n    if ch == \"(\":\n        stack.append(ch)\n    else:\n        stack.pop()\nprint(len(stack))", "output": "1", "why": "Two pushes, one pop: one opening bracket is still waiting to be closed."}, {"id": "t9-2", "week": 9, "title": "Best window", "code": "nums = [2, 1, 5, 1]\nk = 2\nbest = max(sum(nums[i:i + k]) for i in range(len(nums) - k + 1))\nprint(best)", "output": "6", "why": "The windows are [2,1]=3, [1,5]=6, [5,1]=6, so the maximum is 6."}, {"id": "t10-1", "week": 10, "title": "Methods that return self", "code": "class Counter:\n    def __init__(self):\n        self.value = 0\n\n    def add(self, n):\n        self.value += n\n        return self\n\nc = Counter()\nc.add(2).add(3)\nprint(c.value)", "output": "5", "why": "add returns the same object, so the second add runs on c too: 0+2+3."}, {"id": "t10-2", "week": 10, "title": "Alias or copy?", "code": "a = [1, 2]\nb = a\nb.append(3)\nc = a.copy()\nc.append(4)\nprint(a, len(c))", "output": "[1, 2, 3] 4", "why": "b is another name for the same list, so a changes. c is a separate copy, so a does not get 4."}, {"id": "t11-1", "week": 11, "title": "Merging normalized keys", "code": "lib = {}\nfor title, mins in [(\"Hades\", 30), (\"hades \", 15), (\"Celeste\", 10)]:\n    key = title.strip().lower()\n    lib[key] = lib.get(key, 0) + mins\nprint(lib)", "output": "{'hades': 45, 'celeste': 10}", "why": "Both Hades spellings normalize to the same key, so their minutes are summed."}, {"id": "t11-2", "week": 11, "title": "Building CSV lines", "code": "rows = [(\"b\", 2), (\"a\", 1)]\nlines = [\"title,minutes\"] + [f\"{t},{m}\" for t, m in sorted(rows)]\nprint(\"\\n\".join(lines))", "output": "title,minutes\na,1\nb,2", "why": "Tuples sort by their first item, and join puts a newline between each line."}, {"id": "t12-1", "week": 12, "title": "Split only once", "code": "line = \"warn | disk | almost full\"\nlevel, msg = line.split(\"|\", 1)\nprint(level.strip().upper(), msg.strip())", "output": "WARN disk | almost full", "why": "maxsplit=1 splits at the first | only, so the message keeps its own | character."}, {"id": "t12-2", "week": 12, "title": "First unique character", "code": "from collections import Counter\ntext = \"aabcb\"\ncounts = Counter(text)\nprint([ch for ch in text if counts[ch] == 1][0])", "output": "c", "why": "a appears twice and b twice; c is the only character with a count of 1."}, {"id": "t13-1", "week": 13, "title": "Parsing flags", "code": "import argparse\np = argparse.ArgumentParser()\np.add_argument(\"--limit\", type=int, default=10)\np.add_argument(\"--dry-run\", action=\"store_true\")\na = p.parse_args([\"--dry-run\"])\nprint(a.limit, a.dry_run)", "output": "10 True", "why": "Unsupplied --limit uses its default. argparse turns --dry-run into the attribute dry_run."}, {"id": "t13-2", "week": 13, "title": "Environment values are text", "code": "env = {\"APP_PORT\": \"abc\"}\nraw = env.get(\"APP_PORT\", \"8000\")\nprint(raw.isdigit(), env.get(\"DEBUG\", \"off\"))", "output": "False off", "why": "The default is only used when the key is missing. APP_PORT exists, but it is not digits."}, {"id": "t14-1", "week": 14, "title": "Where the exception lands", "code": "def safe_div(a, b):\n    if b == 0:\n        raise ValueError(\"zero divisor\")\n    return a / b\n\ntry:\n    print(safe_div(6, 3))\n    print(safe_div(1, 0))\nexcept ValueError as e:\n    print(\"error:\", e)", "output": "2.0\nerror: zero divisor", "why": "/ always returns a float. The second call raises, so control jumps to except."}, {"id": "t14-2", "week": 14, "title": "A fake dependency", "code": "def lookup(key, cache, fetch):\n    if key not in cache:\n        cache[key] = fetch(key)\n    return cache[key]\n\ncalls = []\n\ndef fake(k):\n    calls.append(k)\n    return k.upper()\n\ncache = {}\nprint(lookup(\"a\", cache, fake), lookup(\"a\", cache, fake), len(calls))", "output": "A A 1", "why": "The second lookup hits the cache, so fetch runs only once."}, {"id": "t15-1", "week": 15, "title": "Full-match patterns", "code": "import re\nfor t in [\"GAME-1234\", \"GAME-12345\", \"game-1234\"]:\n    print(bool(re.fullmatch(r\"GAME-\\d{4}\", t)))", "output": "True\nFalse\nFalse", "why": "fullmatch must consume the whole string: five digits fail, and matching is case-sensitive."}, {"id": "t15-2", "week": 15, "title": "Float surprises", "code": "print(0.1 + 0.2 == 0.3, round(0.1 + 0.2, 2) == 0.3)", "output": "False True", "why": "0.1 + 0.2 is 0.30000000000000004 in binary floating point. Rounding hides the error."}, {"id": "t16-1", "week": 16, "title": "Filter and order in SQL", "code": "import sqlite3\ndb = sqlite3.connect(\":memory:\")\ndb.execute(\"CREATE TABLE g(title TEXT, price INT)\")\ndb.executemany(\"INSERT INTO g VALUES (?, ?)\", [(\"A\", 5), (\"B\", 20), (\"C\", 10)])\nrows = db.execute(\"SELECT title FROM g WHERE price <= 10 ORDER BY price DESC\").fetchall()\nprint(rows)", "output": "[('C',), ('A',)]", "why": "B is filtered out. DESC puts the 10 before the 5. Each row is a one-item tuple."}, {"id": "t16-2", "week": 16, "title": "GROUP BY totals", "code": "import sqlite3\ndb = sqlite3.connect(\":memory:\")\ndb.execute(\"CREATE TABLE s(game TEXT, m INT)\")\ndb.executemany(\"INSERT INTO s VALUES (?, ?)\", [(\"A\", 5), (\"B\", 3), (\"A\", 7)])\nprint(db.execute(\"SELECT game, SUM(m) FROM s GROUP BY game ORDER BY game\").fetchall())", "output": "[('A', 12), ('B', 3)]", "why": "GROUP BY collapses rows per game and SUM adds their minutes: A is 5+7."}, {"id": "t17-1", "week": 17, "title": "Encoding a query", "code": "from urllib.parse import urlencode\nprint(\"https://x.com/g?\" + urlencode({\"q\": \"dark souls\", \"page\": 2}))", "output": "https://x.com/g?q=dark+souls&page=2", "why": "urlencode joins pairs with & and encodes the space as +."}, {"id": "t17-2", "week": 17, "title": "Backoff delays", "code": "delays = []\nfor attempt, status in enumerate([503, 503, 200]):\n    if 200 <= status < 300:\n        break\n    delays.append(2 ** attempt)\nprint(delays)", "output": "[1, 2]", "why": "Attempts 0 and 1 fail and add 2**0 and 2**1. The 200 stops the loop before adding anything."}, {"id": "t18-1", "week": 18, "title": "The mutable default trap", "code": "def add(item, bag=[]):\n    bag.append(item)\n    return bag\n\nadd(1)\nprint(add(2))", "output": "[1, 2]", "why": "The default list is created once and shared between calls, so it still holds 1."}, {"id": "t18-2", "week": 18, "title": "A chunking generator", "code": "def chunks(values, size):\n    for i in range(0, len(values), size):\n        yield values[i:i + size]\n\nprint(list(chunks([1, 2, 3, 4, 5], 2)))", "output": "[[1, 2], [3, 4], [5]]", "why": "range steps by 2: slices start at 0, 2, 4. The last slice is shorter."}, {"id": "t19-1", "week": 19, "title": "Recursive sum", "code": "def depth_sum(v):\n    if isinstance(v, int):\n        return v\n    return sum(depth_sum(x) for x in v)\n\nprint(depth_sum([1, [2, [3]], 4]))", "output": "10", "why": "The base case returns ints; lists are summed by recursing into each item: 1+2+3+4."}, {"id": "t19-2", "week": 19, "title": "Heap order", "code": "import heapq\nh = []\nfor name, pr in [(\"b\", 2), (\"a\", 1), (\"c\", 3)]:\n    heapq.heappush(h, (pr, name))\nprint(heapq.heappop(h)[1], len(h))", "output": "a 2", "why": "heappop removes the smallest tuple, which compares priority first."}, {"id": "t20-1", "week": 20, "title": "Paginating a sorted list", "code": "games = [\"Zelda\", \"Hades\", \"Celeste\", \"Doom\"]\nordered = sorted(games)\nprint(ordered[1:3])", "output": "['Doom', 'Hades']", "why": "Sorted: Celeste, Doom, Hades, Zelda. The slice [1:3] takes indices 1 and 2."}, {"id": "t20-2", "week": 20, "title": "Patch only allowed fields", "code": "original = {\"title\": \"Old\", \"completed\": False, \"id\": 7}\nchanges = {\"title\": \"New\", \"id\": 99}\nallowed = {\"title\", \"completed\"}\npatched = {**original, **{k: v for k, v in changes.items() if k in allowed}}\nprint(patched)", "output": "{'title': 'New', 'completed': False, 'id': 7}", "why": "id is not in allowed, so its change is dropped. Later ** entries override earlier ones."}, {"id": "t21-1", "week": 21, "title": "Upsert by id", "code": "existing = [{\"id\": 1, \"v\": \"a\"}, {\"id\": 2, \"v\": \"b\"}]\nincoming = [{\"id\": 2, \"v\": \"B\"}, {\"id\": 3, \"v\": \"c\"}]\nmerged = {r[\"id\"]: r for r in existing + incoming}\nprint([merged[k][\"v\"] for k in sorted(merged)])", "output": "['a', 'B', 'c']", "why": "Later records overwrite earlier ones with the same id, so id 2 keeps the incoming B."}, {"id": "t21-2", "week": 21, "title": "Validating file names", "code": "import re\nfor n in [\"save_1.json\", \"../x.json\", \"a b.json\"]:\n    print(bool(re.fullmatch(r\"[A-Za-z0-9_-]{1,40}\\.json\", n)))", "output": "True\nFalse\nFalse", "why": "The character class allows no dots or slashes before .json, and no spaces."}, {"id": "t22-1", "week": 22, "title": "Which fields changed?", "code": "before = {\"a\": 1, \"b\": 2}\nafter = {\"a\": 1, \"b\": 3, \"c\": 4}\nprint(sorted(k for k in before.keys() | after.keys() if before.get(k) != after.get(k)))", "output": "['b', 'c']", "why": "b changed value and c is new (None vs 4). a is identical in both."}, {"id": "t22-2", "week": 22, "title": "New and fixed failures", "code": "prev = {\"t1\", \"t2\"}\ncur = {\"t2\", \"t3\"}\nprint(sorted(cur - prev), sorted(prev - cur))", "output": "['t3'] ['t1']", "why": "cur - prev is newly failing; prev - cur is what got fixed. t2 is still failing."}, {"id": "t23-1", "week": 23, "title": "Summarizing CI jobs", "code": "jobs = [{\"name\": \"lint\", \"code\": 0}, {\"name\": \"test\", \"code\": 1}]\nfailed = [j[\"name\"] for j in jobs if j[\"code\"] != 0]\nprint(not failed, failed)", "output": "False ['test']", "why": "A non-empty list is truthy, so not failed is False."}, {"id": "t23-2", "week": 23, "title": "is True means the bool", "code": "evidence = {\"tests\": True, \"readme\": \"yes\"}\nprint(all(evidence.get(k) is True for k in [\"tests\", \"readme\"]))", "output": "False", "why": "\"yes\" is truthy but it is not the object True, so the check fails."}, {"id": "t24-1", "week": 24, "title": "Sort with a tiebreak", "code": "scores = {\"ana\": 5, \"bo\": 9, \"cy\": 9}\nprint(sorted(scores, key=lambda n: (-scores[n], n))[:2])", "output": "['bo', 'cy']", "why": "Negating sorts scores descending; ties fall back to the name ascending."}, {"id": "t24-2", "week": 24, "title": "Sliding window state", "code": "text = \"abcabcbb\"\nbest = start = 0\nseen = {}\nfor i, ch in enumerate(text):\n    if ch in seen and seen[ch] >= start:\n        start = seen[ch] + 1\n    seen[ch] = i\n    best = max(best, i - start + 1)\nprint(best)", "output": "3", "why": "The window never holds more than 3 distinct characters in a row, like abc."}];
